# Example: Reactive agent configuration for certification renewal (AWS Lambda + DynamoDB)
import boto3
from datetime import datetime, timedelta

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table('CertificationInventory')

def lambda_handler(event, context):
    # Scan for certifications expiring in 30 days
    threshold = datetime.now() + timedelta(days=30)
    response = table.scan(
        FilterExpression='expiration_date BETWEEN :now AND :threshold',
        ExpressionAttributeValues={
            ':now': datetime.now().isoformat(),
            ':threshold': threshold.isoformat()
        }
    )

    for cert in response['Items']:
        send_renewal_notification(cert['employee_id'], cert['cert_name'])

    return {'statusCode': 200, 'body': f"Processed {len(response['Items'])} renewals"}

# Thompson Sampling for contextual content recommendation
import numpy as np
from scipy.stats import beta

class ThompsonSamplingAgent:
    def __init__(self, n_arms):
        self.successes = np.ones(n_arms)  # Beta prior α
        self.failures = np.ones(n_arms)   # Beta prior β

    def select_arm(self, context=None):
        samples = [beta.rvs(self.successes[i], self.failures[i]) 
                   for i in range(len(self.successes))]
        return np.argmax(samples)

    def update(self, arm, reward):
        if reward > 0.7:  # threshold for "success"
            self.successes[arm] += 1
        else:
            self.failures[arm] += 1

